import test from 'node:test';import assert from 'node:assert/strict';import {makeReferenceMon} from '../lib/rogue-reference.mjs';import {createClassicCombat,restoreClassicNativeBattle,snapshotClassicNativeBattle,playClassicCombat} from '../lib/rogue-battle-engine.mjs';import {encodeGameData,decodeGameData} from '../lib/game-storage.mjs';
function fixture({modern=true,firstHp=1,secondHp=null,move='Swift',count=2,firstSequential=false,firstRule=null,protectedFirst=false,foeAbility='runaway',heroAbility='noguard',foeSpecies=143}={}){const hero=makeReferenceMon(151,50,{boxId:'hero',moves:[move],ability:heroAbility}),ally=makeReferenceMon(143,100,{boxId:'ally',moves:['Splash'],ability:'runaway'}),foe1=makeReferenceMon(foeSpecies,100,{boxId:'foe1',moves:[protectedFirst?'Protect':'Splash'],ability:foeAbility}),foe2=makeReferenceMon(foeSpecies,100,{boxId:'foe2',moves:['Splash'],ability:'runaway'});foe1.hp=firstHp;if(secondHp!==null)foe2.hp=secondHp;const run={id:'lens-faint',seed:'lens-faint',rng:42,wave:20,screen:'battle',party:[hero,ally],modifiers:[{id:'multilens',boxId:'hero',count}],tools:{},encounter:{kind:'trainer'},multiLensRule:'source-subset-v2',multiLensSpreadRule:'source-v1',...((firstRule||firstSequential)?{multiLensFirstHitRule:firstRule||'swift-source-v1'}:{}),...(modern?{multiLensSpreadFaintRule:'source-v1'}:{})};run.combat=createClassicCombat(run,[foe1,foe2],{trainer:true,doubles:true});return run;}
async function act(run,move='swift',alwaysChance=false,forceSecondary=false,speedBoost=false){const doc=await decodeGameData(await encodeGameData({run,other:{keep:true}}));run=doc.run;const b=restoreClassicNativeBattle(run.combat,run),hits=[];b.randomizer=n=>n;b.randomChance=()=>alwaysChance;if(speedBoost){b.p1.active[0].boosts.spe=6;b.p1.active[0].updateSpeed();}if(forceSecondary)b.random=()=>0;b.onEvent('Damage',b.format,{priority:-100},function(value,target,source,effect){if(source?.side===this.p1&&effect?.id===move)hits.push({id:target.set.trainerToken,value});});b.makeChoices(`move ${move},move splash`,`${run.combat.teams[1][0].moves.includes('Protect')?'move protect':'move splash'},move splash`);run.combat.snapshot=snapshotClassicNativeBattle(b);const saved=await decodeGameData(await encodeGameData({run,other:doc.other}));assert.deepEqual(saved.other,{keep:true});return {b:restoreClassicNativeBattle(saved.run.combat,saved.run),hits};}
test('later hits remove the spread penalty after one opponent faints',async()=>{const current=await act(fixture()),old=await act(fixture({modern:false})),a=current.hits.filter(h=>h.id==='foe2'),b=old.hits.filter(h=>h.id==='foe2');assert.equal(a.length,3);assert.equal(b.length,3);assert.equal(a[0].value,b[0].value);assert.ok(a[1].value>b[1].value,JSON.stringify({a,b}));assert.ok(a[2].value>b[2].value,JSON.stringify({a,b}));});
test('the spread penalty remains while both opponents are alive',async()=>{const current=await act(fixture({firstHp:300})),old=await act(fixture({firstHp:300,modern:false}));assert.deepEqual(current.hits,old.hits);});
test('Surf retains spread penalty while an ally and an opponent remain',async()=>{const current=await act(fixture({move:'Surf'}),'surf'),old=await act(fixture({move:'Surf',modern:false}),'surf');assert.deepEqual(current.hits,old.hits);});
