test('Core Enforcer suppresses Cloud Nine between targets on the second hit after breaking a substitute',async()=>{async function trial(rule){const r=fixture({move:'Core Enforcer',firstHp:300,secondHp:300,foeAbility:'cloudnine',heroAbility:'solarpower',firstRule:'core-enforcer-source-v1'});r.coreEnforcerEarlyRule=rule;r.combat=createClassicCombat(r,r.combat.teams[1],{trainer:true,doubles:true});const b=restoreClassicNativeBattle(r.combat,r),first=b.p2.active[0],hits=[];b.field.setWeather('sunnyday',b.p1.active[0]);first.boosts.spe=6;first.updateSpeed();first.volatiles.substitute=b.initEffectState({id:'substitute',target:first,hp:1});b.randomizer=n=>n;b.randomChance=()=>true;b.onEvent('Damage',b.format,{priority:-100},function(value,target,source,effect){if(source?.side===this.p1&&effect?.id==='coreenforcer'&&target.set.trainerToken==='foe2')hits.push(value);});b.makeChoices('move coreenforcer,move splash','move splash,move splash');r.combat.snapshot=snapshotClassicNativeBattle(b);const doc=await decodeGameData(await encodeGameData({run:r,other:{keep:true}}));assert.equal(doc.run.combat.coreEnforcerEarlyRule,rule);assert.deepEqual(doc.other,{keep:true});return hits;}const current=await trial('source-v2'),old=await trial('source-v1');assert.equal(current.length,3);assert.equal(current[0],old[0]);assert.ok(current[1]>old[1],JSON.stringify({current,old}));});

test('Core Enforcer does not suppress a protected, substituted, shielded, unacted or unsuppressible first foe under the later-hit policy',async()=>{for(const mode of ['protect','substitute','shield','unacted','unsuppressible']){const r=fixture({move:'Core Enforcer',firstHp:300,secondHp:300,foeAbility:mode==='unsuppressible'?'multitype':'cloudnine',heroAbility:'noguard',firstRule:'core-enforcer-source-v1',protectedFirst:mode==='protect'});r.coreEnforcerEarlyRule='source-v2';if(mode==='shield')r.combat.teams[1][0].item='abilityshield';r.combat=createClassicCombat(r,r.combat.teams[1],{trainer:true,doubles:true});const b=restoreClassicNativeBattle(r.combat,r),first=b.p2.active[0],observed=[];if(mode!=='unacted'&&mode!=='protect'){first.boosts.spe=6;first.updateSpeed();}if(mode==='substitute')first.volatiles.substitute=b.initEffectState({id:'substitute',target:first,hp:200});b.randomizer=n=>n;b.randomChance=()=>true;b.onEvent('Damage',b.format,{priority:-100},function(_value,target,source,effect){if(source?.side===this.p1&&effect?.id==='coreenforcer'&&target.set.trainerToken==='foe2'&&observed.length===0)observed.push(!!first.volatiles.gastroacid);});b.makeChoices('move coreenforcer,move splash',`${mode==='protect'?'move protect':'move splash'},move splash`);assert.deepEqual(observed,[false],mode);}});
test('enemy Core Enforcer suppresses Cloud Nine before the second target on later hit',async()=>{async function trial(rule){const hero=makeReferenceMon(143,100,{boxId:'hero',moves:['Splash'],ability:'cloudnine'}),ally=makeReferenceMon(143,100,{boxId:'ally',moves:['Splash'],ability:'runaway'}),foe=makeReferenceMon(151,50,{boxId:'foe',moves:['Core Enforcer'],ability:'solarpower'}),partner=makeReferenceMon(7,100,{boxId:'partner',moves:['Splash']}),run={id:'enemy-core-later',seed:'enemy-core-later',rng:42,wave:20,screen:'battle',party:[hero,ally],modifiers:[{id:'multilens',boxId:'foe',count:2}],tools:{},encounter:{kind:'trainer'},multiLensRule:'source-subset-v2',multiLensSpreadRule:'source-v1',multiLensSpreadFaintRule:'source-v1',multiLensFirstHitRule:'core-enforcer-source-v1',coreEnforcerEarlyRule:rule};run.combat=createClassicCombat(run,[foe,partner],{trainer:true,doubles:true});const b=restoreClassicNativeBattle(run.combat,run),first=b.p1.active[0],hits=[];b.field.setWeather('sunnyday',b.p2.active[0]);first.boosts.spe=6;first.updateSpeed();first.volatiles.substitute=b.initEffectState({id:'substitute',target:first,hp:1});b.randomizer=n=>n;b.randomChance=()=>true;b.onEvent('Damage',b.format,{priority:-100},function(value,target,source,effect){if(source?.side===this.p2&&effect?.id==='coreenforcer'&&target.set.trainerToken==='ally')hits.push(value);});b.makeChoices('move splash,move splash','move coreenforcer,move splash');run.combat.snapshot=snapshotClassicNativeBattle(b);const doc=await decodeGameData(await encodeGameData({run,other:{keep:true}}));assert.equal(doc.run.combat.coreEnforcerEarlyRule,rule);assert.deepEqual(doc.other,{keep:true});return hits;}const current=await trial('source-v2'),old=await trial('source-v1');assert.equal(current.length,3);assert.equal(current[0],old[0]);assert.ok(current[1]>old[1],JSON.stringify({current,old}));});

for(const [name,id] of [['Boomburst','boomburst'],['Sludge Wave','sludgewave']]){
 test(`${name} hits opponents before ally and updates spread reduction`,async()=>{const opt={move:name,secondHp:1},current=await act(fixture({...opt,firstRule:'boomburst-sludge-source-v1'}),id),old=await act(fixture({...opt,firstRule:'core-enforcer-source-v1'}),id);assert.deepEqual(current.hits.slice(0,3).map(h=>h.id),['foe1','foe2','ally']);assert.ok(current.hits.find(h=>h.id==='ally').value>old.hits.find(h=>h.id==='ally').value);});
 test(`${name} retains spread reduction when an opponent protects`,async()=>{const opt={move:name,secondHp:1,protectedFirst:true},current=await act(fixture({...opt,firstRule:'boomburst-sludge-source-v1'}),id),old=await act(fixture({...opt,firstRule:'core-enforcer-source-v1'}),id);assert.ok(current.b.p2.pokemon[0].hp>0);assert.equal(current.hits.find(h=>h.id==='ally').value,old.hits.find(h=>h.id==='ally').value);});
 test(`${name} real turn damages ally and preserves another slot after recovery`,async()=>{let doc=await decodeGameData(await encodeGameData({run:fixture({move:name,secondHp:1,firstRule:'boomburst-sludge-source-v1'}),other:{keep:true}}));const hp=doc.run.party[1].hp;doc.run.combat=playClassicCombat(doc.run,{type:'turn',actions:[{actor:0,type:'move',move:id},{actor:1,type:'move',move:'splash'}]});doc.run.party=doc.run.combat.teams[0];assert.equal(doc.run.combat.winner,0);assert.ok(doc.run.party[1].hp<hp);doc=await decodeGameData(await encodeGameData(doc));assert.deepEqual(doc.other,{keep:true});assert.equal(doc.run.combat.multiLensFirstHitRule,'boomburst-sludge-source-v1');});
}
